public class BankAccount
{
    // Private backing field - inaccessible from outside
    private decimal balance;

    // Public read-only property
    public decimal Balance
    {
        get { return balance; }
        private set // Only settable from within this class
        {
            if (value < 0)
                throw new ArgumentOutOfRangeException(nameof(value), "Balance cannot be negative.");
            balance = value;
        }
    }

    public string AccountNumber { get; }
    public string OwnerName { get; set; }
    public bool IsActive { get; private set; } = true;

    public BankAccount(string accountNumber, string ownerName, decimal initialBalance = 0)
    {
        AccountNumber = accountNumber ?? throw new ArgumentNullException(nameof(accountNumber));
        OwnerName = ownerName ?? throw new ArgumentNullException(nameof(ownerName));
        Balance = initialBalance; // Uses the property's validation
    }

    // Public method to modify balance - the ONLY way to add money
    public bool Deposit(decimal amount)
    {
        if (!IsActive || amount <= 0) return false;
        Balance += amount;
        return true;
    }

    public bool Withdraw(decimal amount)
    {
        if (!IsActive || amount <= 0 || amount > Balance) return false;
        Balance -= amount;
        return true;
    }

    public void CloseAccount()
    {
        IsActive = false;
    }
}

public class Employee
{
    // Auto-property (compiler generates a hidden backing field)
    public string FirstName { get; set; }

    // Init-only property — set only during object initialization
    public string LastName { get; init; }

    // Read-only auto-property — set only in constructor
    public Guid Id { get; } = Guid.NewGuid();

    // Computed (expression-bodied) property
    public string FullName => $"{FirstName} {LastName}";

    // Private setter
    public string Department { get; private set; }

    // Full property with backing field and validation
    private decimal salary;
    public decimal Salary
    {
        get { return salary; }
        set { salary = value >= 0 ? value : throw new ArgumentOutOfRangeException(); }
    }

    // Indexer — allows array-like access
    private string[] skills = new string[0];
    public string this[int index]
    {
        get => skills[index];
        set => skills[index] = value;
    }

    public Employee(string firstName, string lastName, decimal salary, string department)
    {
        FirstName = firstName;
        LastName = lastName;
        Salary = salary;
        Department = department;
    }
}

public class CourseEnrollment
{
    public string StudentId { get; }
    public string CourseCode { get; }
    private DateTime enrollmentDate;
    private char grade;

    public DateTime EnrollmentDate
    {
        get => enrollmentDate;
        private set
        {
            if (value > DateTime.UtcNow)
                throw new ArgumentException("Enrollment date cannot be in the future.");
            enrollmentDate = value;
        }
    }

    public char Grade
    {
        get => grade;
        set
        {
            char[] validGrades = { 'A', 'B', 'C', 'D', 'F' };
            if (!validGrades.Contains(char.ToUpperInvariant(value)))
                throw new ArgumentException($"'{value}' is not a valid grade.");
            grade = char.ToUpperInvariant(value);
        }
    }

    public bool IsPassing => grade != 'F';

    public CourseEnrollment(string studentId, string courseCode)
    {
        StudentId = studentId ?? throw new ArgumentNullException(nameof(studentId));
        CourseCode = courseCode ?? throw new ArgumentNullException(nameof(courseCode));
        EnrollmentDate = DateTime.UtcNow;
    }
}
